F({name:'Glassmorphism CSS Generator',id:'glassmorphism-generator',kw:'frosted glass blur card',desc:'Generate frosted-glass UI cards with CSS',run(r){const bl=h('input',{class:'uin',type:'range',min:0,max:40,value:14}),tr=h('input',{class:'uin',type:'range',min:0,max:60,value:12}),bo=h('input',{class:'uin',type:'range',min:0,max:60,value:20});const col=U.inp({type:'color',value:'#ffffff'});const card=h('div',{style:'width:min(320px,80%);height:190px;border-radius:24px;padding:24px;color:#fff;font-family:Unbounded'},'Glass card');const stage=h('div',{style:'margin-top:14px;border-radius:22px;padding:60px 20px;display:grid;place-items:center;background:radial-gradient(circle at 25% 30%,#ff2e88,transparent 40%),radial-gradient(circle at 75% 70%,#9b3cff,transparent 45%),radial-gradient(circle at 60% 20%,#3cc8ff,transparent 35%),#0e0b13'},card);const code=U.ta({readonly:true,rows:5});
  const run=()=>{const [R,G,B]=hex2rgb(col.value);card.style.background=`rgba(${R},${G},${B},${tr.value/100})`;card.style.backdropFilter=card.style.webkitBackdropFilter=`blur(${bl.value}px)`;card.style.border=`1px solid rgba(${R},${G},${B},${bo.value/100})`;code.value=`background: rgba(${R}, ${G}, ${B}, ${tr.value/100});\nbackdrop-filter: blur(${bl.value}px);\n-webkit-backdrop-filter: blur(${bl.value}px);\nborder: 1px solid rgba(${R}, ${G}, ${B}, ${bo.value/100});\nborder-radius: 24px;`};
  r.append(U.row(U.field('Blur',bl),U.field('Transparency',tr),U.field('Border',bo),U.field('Tint',col)),stage,h('div',{class:'urow'},U.field('CSS',code,'full')),U.copy(()=>code.value));r.addEventListener('input',run);run()}});

F({name:'2048',id:'2048-game',kw:'game puzzle play',desc:'Play the classic 2048 puzzle — arrows or swipe',run(r){let g,score=0,best=0;try{best=+localStorage.getItem('tv_2048')||0}catch(e){}const board=h('div',{style:'display:grid;grid-template-columns:repeat(4,1fr);gap:10px;max-width:420px;margin:16px auto;padding:10px;border-radius:18px;background:rgba(255,255,255,.04);border:1px solid var(--line);touch-action:none'});const sc=h('p',{style:'text-align:center;font-family:Unbounded'});
  const C={2:'#2a1f33',4:'#3a2348',8:'#7a2a6a',16:'#a52a73',32:'#c92a7a',64:'#ff2e88',128:'#ff5fa8',256:'#b03cff',512:'#9b3cff',1024:'#6e3cff',2048:'#ffd23c'};
  const add=()=>{const e=[];g.forEach((v,i)=>!v&&e.push(i));if(e.length)g[e[Math.random()*e.length|0]]=Math.random()<.9?2:4};
  const draw=()=>{board.innerHTML='';g.forEach(v=>board.append(h('div',{style:`aspect-ratio:1;border-radius:12px;display:grid;place-items:center;font-family:Unbounded;font-weight:600;font-size:${v>=1024?20:26}px;background:${v?C[v]||'#ffd23c':'rgba(255,255,255,.05)'}`},v||'')));sc.textContent=`Score ${score} · Best ${best}`};
  const slide=row=>{const a=row.filter(Boolean);for(let i=0;i<a.length-1;i++)if(a[i]===a[i+1]){a[i]*=2;score+=a[i];a.splice(i+1,1)}while(a.length<4)a.push(0);return a};
  const move=d=>{const old=g.join();for(let i=0;i<4;i++){const idx=[0,1,2,3].map(j=>d==='L'||d==='R'?i*4+j:j*4+i);if(d==='R'||d==='D')idx.reverse();const s=slide(idx.map(k=>g[k]));idx.forEach((k,j)=>g[k]=s[j])}if(g.join()!==old){add();sClick();if(score>best){best=score;try{localStorage.setItem('tv_2048',best)}catch(e){}}draw();if(!g.includes(0)&&![0,1,2,3].some(i=>[0,1,2].some(j=>g[i*4+j]===g[i*4+j+1]||g[j*4+i]===g[(j+1)*4+i])))toast('Game over! Score '+score)}};
  const reset=()=>{g=Array(16).fill(0);score=0;add();add();draw()};const kh=e=>{if(!document.contains(board))return removeEventListener('keydown',kh);const d={ArrowLeft:'L',ArrowRight:'R',ArrowUp:'U',ArrowDown:'D'}[e.key];if(d){e.preventDefault();move(d)}};addEventListener('keydown',kh);
  let sx,sy;board.addEventListener('pointerdown',e=>{sx=e.clientX;sy=e.clientY});board.addEventListener('pointerup',e=>{const dx=e.clientX-sx,dy=e.clientY-sy;if(Math.max(Math.abs(dx),Math.abs(dy))<25)return;move(Math.abs(dx)>Math.abs(dy)?(dx>0?'R':'L'):(dy>0?'D':'U'))});
  r.append(sc,board,h('div',{style:'text-align:center'},U.btn('New game',reset,'btn btn-g')));reset()}});

